import React from 'react';
import { jitter } from './jitter';
import type { ExpressionType } from './poses';

interface Props {
  cx: number;
  cy: number;
  scale: number;
  expression: ExpressionType;
  frame: number;
  color?: string;
  strokeWidth?: number;
}

// 表情子组件 — 渲染眼睛、嘴巴、眉毛
export const Face: React.FC<Props> = ({
  cx,
  cy,
  scale,
  expression,
  frame,
  color = '#1c1814',
  strokeWidth = 4,
}) => {
  const s = scale;
  const j = (val: number, seed: number) => val + jitter(frame, seed, 0.6);

  // 眨眼：每 90 帧眨一次，持续 4 帧
  const blink = frame % 90 < 4;

  const eyeY = -8 * s;
  const mouthY = 16 * s;

  const renderEyes = () => {
    if (blink && expression !== 'surprise' && expression !== 'wow') {
      return (
        <>
          <line
            x1={j(cx - 14 * s, 60)}
            y1={j(cy + eyeY, 61)}
            x2={j(cx - 6 * s, 62)}
            y2={j(cy + eyeY, 63)}
            stroke={color}
            strokeWidth={strokeWidth * 0.85}
            strokeLinecap="round"
          />
          <line
            x1={j(cx + 6 * s, 64)}
            y1={j(cy + eyeY, 65)}
            x2={j(cx + 14 * s, 66)}
            y2={j(cy + eyeY, 67)}
            stroke={color}
            strokeWidth={strokeWidth * 0.85}
            strokeLinecap="round"
          />
        </>
      );
    }

    if (expression === 'surprise' || expression === 'wow') {
      return (
        <>
          <circle cx={j(cx - 11 * s, 60)} cy={j(cy + eyeY, 61)} r={6 * s} fill="white" stroke={color} strokeWidth={strokeWidth * 0.7} />
          <circle cx={j(cx - 11 * s, 62)} cy={j(cy + eyeY, 63)} r={3 * s} fill={color} />
          <circle cx={j(cx + 11 * s, 64)} cy={j(cy + eyeY, 65)} r={6 * s} fill="white" stroke={color} strokeWidth={strokeWidth * 0.7} />
          <circle cx={j(cx + 11 * s, 66)} cy={j(cy + eyeY, 67)} r={3 * s} fill={color} />
        </>
      );
    }

    if (expression === 'think') {
      return (
        <>
          <circle cx={j(cx - 11 * s, 60)} cy={j(cy + eyeY, 61)} r={3 * s} fill={color} />
          {/* 右眼眯起 */}
          <path
            d={`M ${j(cx + 5 * s, 62)} ${j(cy + eyeY, 63)} Q ${j(cx + 11 * s, 64)} ${j(cy + eyeY - 4 * s, 65)} ${j(cx + 17 * s, 66)} ${j(cy + eyeY, 67)}`}
            fill="none"
            stroke={color}
            strokeWidth={strokeWidth * 0.85}
            strokeLinecap="round"
          />
        </>
      );
    }

    // happy / point / neutral - 圆点眼
    return (
      <>
        <circle cx={j(cx - 11 * s, 60)} cy={j(cy + eyeY, 61)} r={3.2 * s} fill={color} />
        <circle cx={j(cx + 11 * s, 62)} cy={j(cy + eyeY, 63)} r={3.2 * s} fill={color} />
      </>
    );
  };

  const renderMouth = () => {
    if (expression === 'happy') {
      return (
        <path
          d={`M ${j(cx - 12 * s, 70)} ${j(cy + mouthY - 2 * s, 71)} Q ${j(cx, 72)} ${j(cy + mouthY + 10 * s, 73)} ${j(cx + 12 * s, 74)} ${j(cy + mouthY - 2 * s, 75)}`}
          stroke={color}
          strokeWidth={strokeWidth * 0.9}
          fill="none"
          strokeLinecap="round"
        />
      );
    }
    if (expression === 'surprise' || expression === 'wow') {
      return (
        <ellipse
          cx={j(cx, 70)}
          cy={j(cy + mouthY + 2 * s, 71)}
          rx={6 * s}
          ry={9 * s}
          fill={color}
        />
      );
    }
    if (expression === 'think') {
      return (
        <line
          x1={j(cx - 6 * s, 70)}
          y1={j(cy + mouthY, 71)}
          x2={j(cx + 8 * s, 72)}
          y2={j(cy + mouthY - 3 * s, 73)}
          stroke={color}
          strokeWidth={strokeWidth * 0.85}
          strokeLinecap="round"
        />
      );
    }
    if (expression === 'sad') {
      return (
        <path
          d={`M ${j(cx - 10 * s, 70)} ${j(cy + mouthY + 4 * s, 71)} Q ${j(cx, 72)} ${j(cy + mouthY - 4 * s, 73)} ${j(cx + 10 * s, 74)} ${j(cy + mouthY + 4 * s, 75)}`}
          stroke={color}
          strokeWidth={strokeWidth * 0.85}
          fill="none"
          strokeLinecap="round"
        />
      );
    }
    // neutral / point — 一条直线
    return (
      <line
        x1={j(cx - 8 * s, 70)}
        y1={j(cy + mouthY, 71)}
        x2={j(cx + 8 * s, 72)}
        y2={j(cy + mouthY, 73)}
        stroke={color}
        strokeWidth={strokeWidth * 0.85}
        strokeLinecap="round"
      />
    );
  };

  // 惊讶时加眉毛上扬
  const renderBrows = () => {
    if (expression === 'surprise' || expression === 'wow') {
      return (
        <>
          <line
            x1={j(cx - 18 * s, 80)}
            y1={j(cy + eyeY - 16 * s, 81)}
            x2={j(cx - 4 * s, 82)}
            y2={j(cy + eyeY - 20 * s, 83)}
            stroke={color}
            strokeWidth={strokeWidth * 0.8}
            strokeLinecap="round"
          />
          <line
            x1={j(cx + 4 * s, 84)}
            y1={j(cy + eyeY - 20 * s, 85)}
            x2={j(cx + 18 * s, 86)}
            y2={j(cy + eyeY - 16 * s, 87)}
            stroke={color}
            strokeWidth={strokeWidth * 0.8}
            strokeLinecap="round"
          />
        </>
      );
    }
    return null;
  };

  return (
    <g>
      {renderBrows()}
      {renderEyes()}
      {renderMouth()}
    </g>
  );
};
