import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { getSlideMotionTiming } from "../templates/animationTiming";

// macOS 26 液态玻璃配色
const colors = {
  bg: "#e8e8ed",
  blob1: "#ff6b9d",
  blob2: "#c44dff",
  blob3: "#00d4aa",
  blob4: "#ff9f43",
  blob5: "#5f9eff",
  blob6: "#a855f7",
  text: "#1d1d1f",
  textSecondary: "#424245",
  muted: "#6e6e73",
};

// ===== 超大液态 Blob =====
const MegaBlob: React.FC<{
  frame: number;
  x: number;
  y: number;
  size: number;
  color: string;
  speedX: number;
  speedY: number;
  phase: number;
}> = ({ frame, x, y, size, color, speedX, speedY, phase }) => {
  const moveX = Math.sin(frame * speedX + phase) * 100 + Math.cos(frame * speedX * 0.7) * 50;
  const moveY = Math.cos(frame * speedY + phase) * 80 + Math.sin(frame * speedY * 0.6) * 40;
  const morph1 = 30 + Math.sin(frame * 0.015 + phase) * 25;
  const morph2 = 70 + Math.cos(frame * 0.012 + phase) * 30;
  const morph3 = 50 + Math.sin(frame * 0.018 + phase + 1) * 28;
  const morph4 = 60 + Math.cos(frame * 0.014 + phase + 2) * 22;
  const scale = 1 + Math.sin(frame * 0.008 + phase) * 0.12;

  return (
    <div
      style={{
        position: "absolute",
        left: x + moveX,
        top: y + moveY,
        width: size,
        height: size,
        background: color,
        borderRadius: `${morph1}% ${morph2}% ${morph3}% ${morph4}%`,
        filter: "blur(100px)",
        opacity: 0.85,
        transform: `scale(${scale})`,
      }}
    />
  );
};

// ===== 渐变背景 =====
const GradientBackground: React.FC<{ frame: number }> = ({ frame }) => {
  const shift = Math.sin(frame * 0.005) * 20;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        background: `
          radial-gradient(ellipse 80% 60% at ${50 + shift}% 30%, rgba(255,107,157,0.15) 0%, transparent 60%),
          radial-gradient(ellipse 70% 80% at ${30 + shift * 0.5}% 70%, rgba(196,77,255,0.12) 0%, transparent 55%),
          radial-gradient(ellipse 90% 70% at ${70 - shift * 0.3}% 50%, rgba(0,212,170,0.1) 0%, transparent 50%),
          linear-gradient(180deg, #f0f0f5 0%, #e8e8ed 50%, #e0e0e5 100%)
        `,
      }}
    />
  );
};

// ===== 主毛玻璃卡片 =====
const LiquidGlassCard: React.FC<{
  children: React.ReactNode;
  frame: number;
  delay: number;
  width?: number;
  padding?: string;
}> = ({ children, frame, delay, width = 920, padding = "70px 55px" }) => {
  const progress = spring({
    frame: frame - delay,
    fps: 30,
    config: { damping: 20, stiffness: 100 },
  });

  const breathe = 1 + Math.sin(frame * 0.025) * 0.008;

  return (
    <div
      style={{
        position: "relative",
        opacity: progress,
        transform: `scale(${progress * breathe}) translateY(${(1 - progress) * 20}px)`,
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: -2,
          borderRadius: 46,
          background: "linear-gradient(135deg, rgba(255,255,255,0.8), rgba(255,255,255,0.2))",
          filter: "blur(20px)",
          opacity: 0.5,
        }}
      />

      <div
        style={{
          position: "relative",
          width,
          padding,
          background: `
            linear-gradient(135deg,
              rgba(255,255,255,0.75) 0%,
              rgba(255,255,255,0.65) 50%,
              rgba(255,255,255,0.7) 100%
            )
          `,
          backdropFilter: "blur(80px) saturate(200%)",
          WebkitBackdropFilter: "blur(80px) saturate(200%)",
          borderRadius: 44,
          border: "1px solid rgba(255,255,255,0.8)",
          boxShadow: `
            0 25px 50px -12px rgba(0,0,0,0.08),
            0 12px 24px -8px rgba(0,0,0,0.04),
            0 0 0 1px rgba(255,255,255,0.5),
            inset 0 1px 2px rgba(255,255,255,1),
            inset 0 -1px 1px rgba(0,0,0,0.03)
          `,
        }}
      >
        {children}
      </div>
    </div>
  );
};

// ===== 浮动装饰球 =====
const FloatingSphere: React.FC<{
  frame: number;
  x: number;
  y: number;
  size: number;
  color: string;
  delay: number;
}> = ({ frame, x, y, size, color, delay }) => {
  const progress = spring({
    frame: frame - delay,
    fps: 30,
    config: { damping: 15 },
  });

  const floatY = Math.sin(frame * 0.025 + delay) * 12;
  const floatX = Math.cos(frame * 0.018 + delay * 0.7) * 8;

  return (
    <div
      style={{
        position: "absolute",
        left: x + floatX,
        top: y + floatY,
        width: size,
        height: size,
        borderRadius: "50%",
        background: `
          radial-gradient(circle at 35% 35%,
            rgba(255,255,255,0.9) 0%,
            ${color} 40%,
            ${color}cc 100%
          )
        `,
        boxShadow: `
          0 8px 32px ${color}50,
          inset 0 -6px 12px rgba(0,0,0,0.15),
          inset 0 6px 12px rgba(255,255,255,0.9)
        `,
        opacity: progress * 0.9,
        transform: `scale(${progress})`,
      }}
    />
  );
};

// ===== 玻璃胶囊标签 =====
// ===== 动画数字 =====
const AnimatedNumber: React.FC<{
  value: number;
  suffix?: string;
  startFrame: number;
  color: string;
}> = ({ value, suffix = "", startFrame, color }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const progress = spring({
    frame: frame - startFrame,
    fps,
    config: { damping: 20, stiffness: 50 },
  });

  const displayValue = Math.round(interpolate(progress, [0, 1], [0, value]));

  return (
    <span style={{ fontVariantNumeric: "tabular-nums", color }}>
      {displayValue.toLocaleString()}{suffix}
    </span>
  );
};

// ===== 进度条 =====
const ProgressBar: React.FC<{
  percent: number;
  label: string;
  color: string;
  delay: number;
}> = ({ percent, label, color, delay }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const progress = spring({
    frame: frame - delay,
    fps,
    config: { damping: 15 },
  });

  const width = interpolate(progress, [0, 1], [0, percent]);

  return (
    <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
      <span style={{ fontSize: 22, color: colors.text, width: 100, flexShrink: 0, fontWeight: 500 }}>
        {label}
      </span>
      <div style={{ flex: 1, height: 14, background: "rgba(0,0,0,0.06)", borderRadius: 7, overflow: "hidden" }}>
        <div
          style={{
            width: `${width}%`,
            height: "100%",
            background: `linear-gradient(90deg, ${color}, ${color}cc)`,
            borderRadius: 7,
            boxShadow: `0 2px 12px ${color}50`,
          }}
        />
      </div>
      <span style={{ fontSize: 20, color, fontWeight: 600, width: 50, textAlign: "right" }}>
        {Math.round(width)}%
      </span>
    </div>
  );
};

// ===== 步骤卡片 =====
const StepCard: React.FC<{
  title: string;
  description?: string;
  index: number;
  color: string;
  progress: number;
}> = ({ title, description, index, color, progress }) => {
  return (
    <div
      style={{
        display: "flex",
        gap: 16,
        opacity: progress,
        transform: `translateY(${interpolate(progress, [0, 1], [25, 0])}px)`,
      }}
    >
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
        <div
          style={{
            width: 44,
            height: 44,
            borderRadius: "50%",
            background: `linear-gradient(135deg, ${color}, ${color}cc)`,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            fontSize: 20,
            fontWeight: 700,
            color: "white",
            boxShadow: `0 6px 20px ${color}50`,
          }}
        >
          {index + 1}
        </div>
        <div style={{ width: 2, flex: 1, background: "rgba(0,0,0,0.08)", marginTop: 6 }} />
      </div>
      <div style={{ flex: 1, paddingBottom: 24 }}>
        <h3 style={{ fontSize: 26, fontWeight: 600, color: colors.text, margin: "0 0 4px 0" }}>
          {title}
        </h3>
        {description && (
          <p style={{ fontSize: 20, color: colors.muted, margin: 0 }}>
            {description}
          </p>
        )}
      </div>
    </div>
  );
};

// ===== 时间线项 =====
const TimelineItem: React.FC<{
  year: string;
  title: string;
  description?: string;
  color: string;
  progress: number;
  isLeft: boolean;
}> = ({ year, title, description, color, progress, isLeft }) => {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 16,
        flexDirection: isLeft ? "row" : "row-reverse",
        opacity: progress,
        transform: `translateX(${interpolate(progress, [0, 1], [isLeft ? -30 : 30, 0])}px)`,
      }}
    >
      <div style={{ flex: 1, textAlign: isLeft ? "right" : "left" }}>
        <div style={{ fontSize: 20, fontWeight: 700, color, marginBottom: 2 }}>{year}</div>
        <div style={{ fontSize: 24, fontWeight: 600, color: colors.text, marginBottom: 2 }}>{title}</div>
        {description && (
          <div style={{ fontSize: 18, color: colors.muted }}>{description}</div>
        )}
      </div>
      <div
        style={{
          width: 14,
          height: 14,
          borderRadius: "50%",
          background: color,
          boxShadow: `0 0 16px ${color}`,
          flexShrink: 0,
        }}
      />
      <div style={{ flex: 1 }} />
    </div>
  );
};

// ===== 主组件 =====
export const LiquidSlide: React.FC<{
  title: string;
  subtitle?: string;
  points?: string[];
  type?: 'default' | 'steps' | 'timeline' | 'chart' | 'highlight' | 'list' | 'compare' | 'stats' | 'quote' | 'hero' | 'cta';
  data?: Record<string, unknown>;
  index: number;
  totalSlides: number;
  durationInFrames: number;
}> = ({ title, subtitle, points, type = 'default', data, index, totalSlides, durationInFrames }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // 根据 type 计算动画元素数量
  const getAnimCount = () => {
    if (type === 'steps' && Array.isArray(data?.steps)) return (data.steps as unknown[]).length;
    if (type === 'timeline' && Array.isArray(data?.timeline)) return (data.timeline as unknown[]).length;
    if (type === 'chart' && Array.isArray(data?.bars)) return (data.bars as unknown[]).length;
    if (type === 'stats' && Array.isArray(data?.stats)) return (data.stats as unknown[]).length;
    if (type === 'list' && Array.isArray(data?.items)) return (data.items as unknown[]).length;
    if (type === 'compare') return 2;
    return points?.length ?? 0;
  };

  const timing = getSlideMotionTiming(durationInFrames, getAnimCount());

  const titleProgress = spring({
    frame: frame - timing.titleStart,
    fps,
    config: { damping: 18, stiffness: 100 },
  });

  const subtitleProgress = spring({
    frame: frame - timing.subtitleStart,
    fps,
    config: { damping: 18, stiffness: 90 },
  });

  const pointProgresses = (points || []).map((_, i) =>
    spring({
      frame: frame - timing.pointsStart - i * timing.pointStagger,
      fps,
      config: { damping: 14, stiffness: 100 },
    })
  );

  const exitOpacity = interpolate(
    frame,
    [timing.exitStart, timing.exitEnd],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // ===== 渲染不同类型内容 =====
  const renderContent = () => {
    switch (type) {
      // ===== 统计数据 =====
      case 'stats': {
        const stats = (data?.stats as Array<{ value: number; suffix?: string; label: string; color?: string }>) || [];
        return (
          <div style={{ display: "flex", gap: 24, justifyContent: "center", flexWrap: "wrap", width: "100%" }}>
            {stats.map((stat, i) => {
              const statProgress = spring({
                frame: frame - 10 - i * 8,
                fps,
                config: { damping: 12, stiffness: 100 },
              });
              const statColor = stat.color || [colors.blob1, colors.blob2, colors.blob3, colors.blob4, colors.blob5][i % 5];
              return (
                <div
                  key={i}
                  style={{
                    background: "rgba(255,255,255,0.6)",
                    backdropFilter: "blur(15px)",
                    borderRadius: 24,
                    border: "1px solid rgba(255,255,255,0.8)",
                    padding: "32px 40px",
                    textAlign: "center",
                    opacity: statProgress,
                    transform: `translateY(${interpolate(statProgress, [0, 1], [30, 0])}px) scale(${interpolate(statProgress, [0, 1], [0.9, 1])})`,
                    minWidth: 170,
                    boxShadow: "0 4px 20px rgba(0,0,0,0.04)",
                  }}
                >
                  <div style={{ fontSize: 60, fontWeight: 700, marginBottom: 6 }}>
                    <AnimatedNumber value={stat.value} suffix={stat.suffix} startFrame={15 + i * 8} color={statColor} />
                  </div>
                  <div style={{ fontSize: 22, color: colors.muted }}>{stat.label}</div>
                </div>
              );
            })}
          </div>
        );
      }

      // ===== 对比 =====
      case 'compare': {
        const compareData = data as { left?: { label: string; value: string; desc?: string }; right?: { label: string; value: string; desc?: string }; vsText?: string; vsLabel?: string };
        const leftProgress = spring({ frame: frame - 12, fps, config: { damping: 12 } });
        const rightProgress = spring({ frame: frame - 22, fps, config: { damping: 12 } });
        const coreProgress = spring({ frame: frame - 18, fps, config: { damping: 14, stiffness: 90 } });

        return (
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1fr auto 1fr",
              gap: 18,
              alignItems: "stretch",
              justifyContent: "center",
              width: "100%",
              maxWidth: 760,
              position: "relative",
            }}
          >
            <div
              style={{
                position: "absolute",
                left: "50%",
                top: "50%",
                width: 160,
                height: 2,
                borderRadius: 999,
                background: "linear-gradient(90deg, rgba(255,107,157,0.28) 0%, rgba(255,255,255,0.92) 48%, rgba(0,212,170,0.28) 100%)",
                transform: `translate(-50%, -50%) scaleX(${interpolate(coreProgress, [0, 1], [0.4, 1])})`,
                opacity: interpolate(coreProgress, [0, 1], [0, 1]),
                boxShadow: "0 0 20px rgba(255,255,255,0.5)",
              }}
            />
            <div
              style={{
                flex: 1,
                position: "relative",
                overflow: "hidden",
                background: "linear-gradient(155deg, rgba(255,255,255,0.74) 0%, rgba(255,255,255,0.42) 54%, rgba(255,107,157,0.18) 100%)",
                backdropFilter: "blur(24px) saturate(180%)",
                WebkitBackdropFilter: "blur(24px) saturate(180%)",
                borderRadius: 30,
                border: "1px solid rgba(255,255,255,0.82)",
                padding: "28px 24px 30px",
                minHeight: 204,
                display: "flex",
                flexDirection: "column",
                justifyContent: "space-between",
                textAlign: "left",
                opacity: leftProgress,
                transform: `translateX(${interpolate(leftProgress, [0, 1], [-48, 0])}px) rotate(${interpolate(leftProgress, [0, 1], [-3, -1])}deg)`,
                boxShadow: `
                  0 24px 44px rgba(255,107,157,0.16),
                  0 8px 18px rgba(255,255,255,0.32),
                  inset 0 1px 0 rgba(255,255,255,0.95),
                  inset 0 -1px 0 rgba(255,107,157,0.12)
                `,
              }}
            >
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  background: "radial-gradient(circle at 20% 18%, rgba(255,255,255,0.88) 0%, rgba(255,255,255,0) 38%), radial-gradient(circle at 86% 100%, rgba(255,107,157,0.18) 0%, rgba(255,107,157,0) 48%)",
                  pointerEvents: "none",
                }}
              />
              <div style={{ position: "relative", zIndex: 1 }}>
                <div
                  style={{
                    display: "inline-flex",
                    alignItems: "center",
                    gap: 8,
                    padding: "8px 14px",
                    borderRadius: 999,
                    background: "rgba(255,255,255,0.62)",
                    border: "1px solid rgba(255,255,255,0.9)",
                    boxShadow: "inset 0 1px 0 rgba(255,255,255,0.96)",
                    marginBottom: 22,
                  }}
                >
                  <span style={{ width: 10, height: 10, borderRadius: "50%", background: colors.blob1, boxShadow: `0 0 14px ${colors.blob1}80` }} />
                  <span style={{ fontSize: 15, color: colors.blob1, fontWeight: 700, letterSpacing: "0.02em" }}>
                    {compareData?.left?.label || "Before"}
                  </span>
                </div>
                <div style={{ fontSize: 48, fontWeight: 700, color: colors.text, marginBottom: 10, letterSpacing: "-0.04em" }}>
                  {compareData?.left?.value || "-"}
                </div>
                {compareData?.left?.desc && (
                  <div style={{ fontSize: 18, color: colors.textSecondary, lineHeight: 1.5, maxWidth: 220 }}>
                    {compareData.left.desc}
                  </div>
                )}
              </div>
              <div
                style={{
                  position: "relative",
                  zIndex: 1,
                  marginTop: 24,
                  paddingTop: 18,
                  borderTop: "1px solid rgba(255,107,157,0.14)",
                  fontSize: 13,
                  fontWeight: 600,
                  color: "rgba(255,107,157,0.8)",
                  letterSpacing: "0.12em",
                  textTransform: "uppercase",
                }}
              >
                {compareData?.left?.label || "Old Rhythm"}
              </div>
            </div>

            <div
              style={{
                width: 94,
                minWidth: 94,
                alignSelf: "center",
                height: 94,
                borderRadius: "50% 50% 44% 44%",
                background: "linear-gradient(180deg, rgba(255,255,255,0.94) 0%, rgba(255,255,255,0.72) 100%)",
                backdropFilter: "blur(20px)",
                WebkitBackdropFilter: "blur(20px)",
                display: "flex",
                flexDirection: "column",
                justifyContent: "center",
                alignItems: "center",
                fontSize: 22,
                fontWeight: 700,
                color: colors.text,
                flexShrink: 0,
                transform: `scale(${interpolate(coreProgress, [0, 1], [0.7, 1])})`,
                opacity: coreProgress,
                border: "1px solid rgba(255,255,255,0.95)",
                boxShadow: `
                  0 18px 34px rgba(145, 87, 255, 0.16),
                  inset 0 1px 0 rgba(255,255,255,0.96),
                  inset 0 -10px 20px rgba(145, 87, 255, 0.08)
                `,
              }}
            >
              <div
                style={{
                  fontSize: 12,
                  letterSpacing: "0.18em",
                  color: colors.muted,
                  marginBottom: 4,
                }}
              >
                {compareData?.vsLabel || "FLOW"}
              </div>
              <div>{compareData?.vsText || "VS"}</div>
            </div>

            <div
              style={{
                flex: 1,
                position: "relative",
                overflow: "hidden",
                background: "linear-gradient(205deg, rgba(255,255,255,0.8) 0%, rgba(255,255,255,0.46) 52%, rgba(0,212,170,0.18) 100%)",
                backdropFilter: "blur(24px) saturate(180%)",
                WebkitBackdropFilter: "blur(24px) saturate(180%)",
                borderRadius: 30,
                border: "1px solid rgba(255,255,255,0.82)",
                padding: "28px 24px 30px",
                minHeight: 204,
                display: "flex",
                flexDirection: "column",
                justifyContent: "space-between",
                textAlign: "left",
                opacity: rightProgress,
                transform: `translateX(${interpolate(rightProgress, [0, 1], [48, 0])}px) rotate(${interpolate(rightProgress, [0, 1], [3, 1])}deg)`,
                boxShadow: `
                  0 24px 44px rgba(0,212,170,0.16),
                  0 8px 18px rgba(255,255,255,0.32),
                  inset 0 1px 0 rgba(255,255,255,0.95),
                  inset 0 -1px 0 rgba(0,212,170,0.12)
                `,
              }}
            >
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  background: "radial-gradient(circle at 82% 16%, rgba(255,255,255,0.92) 0%, rgba(255,255,255,0) 34%), radial-gradient(circle at 18% 100%, rgba(0,212,170,0.18) 0%, rgba(0,212,170,0) 48%)",
                  pointerEvents: "none",
                }}
              />
              <div style={{ position: "relative", zIndex: 1 }}>
                <div
                  style={{
                    display: "inline-flex",
                    alignItems: "center",
                    gap: 8,
                    padding: "8px 14px",
                    borderRadius: 999,
                    background: "rgba(255,255,255,0.66)",
                    border: "1px solid rgba(255,255,255,0.92)",
                    boxShadow: "inset 0 1px 0 rgba(255,255,255,0.98)",
                    marginBottom: 22,
                  }}
                >
                  <span style={{ width: 10, height: 10, borderRadius: "50%", background: colors.blob3, boxShadow: `0 0 14px ${colors.blob3}80` }} />
                  <span style={{ fontSize: 15, color: colors.blob3, fontWeight: 700, letterSpacing: "0.02em" }}>
                    {compareData?.right?.label || "After"}
                  </span>
                </div>
                <div style={{ fontSize: 48, fontWeight: 700, color: colors.text, marginBottom: 10, letterSpacing: "-0.04em" }}>
                  {compareData?.right?.value || "+"}
                </div>
                {compareData?.right?.desc && (
                  <div style={{ fontSize: 18, color: colors.textSecondary, lineHeight: 1.5, maxWidth: 220 }}>
                    {compareData.right.desc}
                  </div>
                )}
              </div>
              <div
                style={{
                  position: "relative",
                  zIndex: 1,
                  marginTop: 24,
                  paddingTop: 18,
                  borderTop: "1px solid rgba(0,212,170,0.16)",
                  fontSize: 13,
                  fontWeight: 600,
                  color: "rgba(0,212,170,0.88)",
                  letterSpacing: "0.12em",
                  textTransform: "uppercase",
                }}
              >
                {compareData?.right?.label || "New Focus"}
              </div>
            </div>
          </div>
        );
      }

      // ===== 步骤 =====
      case 'steps': {
        const steps = (data?.steps as Array<{ title: string; description?: string }>) || [];
        return (
          <div style={{ display: "flex", flexDirection: "column", gap: 0, width: "100%", maxWidth: 650 }}>
            {steps.map((step, i) => {
              const stepProgress = spring({
                frame: frame - 10 - i * 10,
                fps,
                config: { damping: 12, stiffness: 100 },
              });
              const stepColor = [colors.blob1, colors.blob2, colors.blob3, colors.blob4, colors.blob5][i % 5];
              return (
                <StepCard
                  key={i}
                  title={step.title}
                  description={step.description}
                  index={i}
                  color={stepColor}
                  progress={stepProgress}
                />
              );
            })}
          </div>
        );
      }

      // ===== 图表 =====
      case 'chart': {
        const bars = (data?.bars as Array<{ label: string; value: number; color?: string }>) || [];
        return (
          <div style={{ display: "flex", flexDirection: "column", gap: 16, width: "100%", maxWidth: 650 }}>
            {bars.map((bar, i) => {
              const barColor = bar.color || [colors.blob1, colors.blob2, colors.blob3, colors.blob4, colors.blob5][i % 5];
              return (
                <ProgressBar
                  key={i}
                  percent={bar.value}
                  label={bar.label}
                  color={barColor}
                  delay={10 + i * 8}
                />
              );
            })}
          </div>
        );
      }

      // ===== 列表 =====
      case 'list': {
        const items = (data?.items as Array<{ icon?: string; text: string; desc?: string }>) || [];
        const blobColors = [colors.blob1, colors.blob2, colors.blob3, colors.blob4, colors.blob5];
        return (
          <div style={{ display: "flex", flexDirection: "column", gap: 14, width: "100%", maxWidth: 650 }}>
            {items.map((item, i) => {
              const itemProgress = spring({
                frame: frame - 8 - i * 8,
                fps,
                config: { damping: 12, stiffness: 100 },
              });
              const itemColor = blobColors[i % blobColors.length];
              return (
                <div
                  key={i}
                  style={{
                    display: "flex",
                    gap: 18,
                    alignItems: "center",
                    background: "rgba(255,255,255,0.62)",
                    backdropFilter: "blur(20px)",
                    borderRadius: 20,
                    padding: "20px 24px",
                    border: "1px solid rgba(255,255,255,0.85)",
                    boxShadow: `0 4px 16px rgba(0,0,0,0.06), 0 0 0 1px ${itemColor}18`,
                    opacity: itemProgress,
                    transform: `translateY(${interpolate(itemProgress, [0, 1], [24, 0])}px)`,
                  }}
                >
                  {/* Colored icon circle */}
                  <div
                    style={{
                      width: 48,
                      height: 48,
                      borderRadius: "50%",
                      background: `${itemColor}22`,
                      border: `2px solid ${itemColor}55`,
                      display: "flex",
                      justifyContent: "center",
                      alignItems: "center",
                      fontSize: 24,
                      flexShrink: 0,
                    }}
                  >
                    {item.icon || "✦"}
                  </div>
                  {/* Text */}
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: 26, fontWeight: 600, color: colors.text, lineHeight: 1.2 }}>{item.text}</div>
                    {item.desc && (
                      <div style={{ fontSize: 20, color: colors.muted, marginTop: 4 }}>{item.desc}</div>
                    )}
                  </div>
                  {/* Color dot accent */}
                  <div style={{ width: 10, height: 10, borderRadius: "50%", background: itemColor, flexShrink: 0 }} />
                </div>
              );
            })}
          </div>
        );
      }

      // ===== 时间线 =====
      case 'timeline': {
        const timeline = (data?.timeline as Array<{ year: string; title: string; description?: string }>) || [];
        return (
          <div style={{ display: "flex", flexDirection: "column", gap: 20, width: "100%", maxWidth: 700, position: "relative" }}>
            <div style={{
              position: "absolute",
              left: "50%",
              top: 16,
              bottom: 16,
              width: 2,
              background: "rgba(0,0,0,0.08)",
              transform: "translateX(-50%)",
            }} />
            {timeline.map((item, i) => {
              const tlProgress = spring({
                frame: frame - 10 - i * 12,
                fps,
                config: { damping: 12, stiffness: 100 },
              });
              const tlColor = [colors.blob1, colors.blob2, colors.blob3, colors.blob4, colors.blob5][i % 5];
              return (
                <TimelineItem
                  key={i}
                  year={item.year}
                  title={item.title}
                  description={item.description}
                  color={tlColor}
                  progress={tlProgress}
                  isLeft={i % 2 === 0}
                />
              );
            })}
          </div>
        );
      }

      // ===== 高亮 =====
      case 'highlight': {
        const items = (data?.items as string[]) || [];
        return (
          <div style={{ display: "flex", flexWrap: "wrap", gap: 14, justifyContent: "center", width: "100%", maxWidth: 750 }}>
            {items.map((item, i) => {
              const hlProgress = spring({
                frame: frame - 6 - i * 5,
                fps,
                config: { damping: 12, stiffness: 100 },
              });
              const hlColor = [colors.blob1, colors.blob2, colors.blob3, colors.blob4, colors.blob5][i % 5];
              return (
                <div
                  key={i}
                  style={{
                    background: `${hlColor}15`,
                    backdropFilter: "blur(15px)",
                    borderRadius: 18,
                    border: `2px solid ${hlColor}50`,
                    padding: "16px 30px",
                    opacity: hlProgress,
                    transform: `scale(${interpolate(hlProgress, [0, 1], [0.8, 1])})`,
                    boxShadow: `0 4px 20px ${hlColor}25`,
                  }}
                >
                  <span style={{ fontSize: 24, fontWeight: 600, color: colors.text }}>{item}</span>
                </div>
              );
            })}
          </div>
        );
      }

      // ===== 引用 =====
      case 'quote': {
        const quoteData = data as { quote?: string; author?: string };
        const quoteProgress = spring({ frame: frame - 10, fps, config: { damping: 15 } });
        return (
          <div
            style={{
              background: "rgba(255,255,255,0.55)",
              backdropFilter: "blur(20px)",
              borderRadius: 28,
              border: "1px solid rgba(255,255,255,0.8)",
              padding: "44px 50px",
              maxWidth: 750,
              opacity: quoteProgress,
              transform: `translateY(${interpolate(quoteProgress, [0, 1], [30, 0])}px)`,
              boxShadow: "0 4px 24px rgba(0,0,0,0.04)",
            }}
          >
            <div style={{ fontSize: 70, color: colors.blob2, marginBottom: 8, lineHeight: 1 }}>"</div>
            <p style={{ fontSize: 32, fontStyle: "italic", color: colors.text, margin: 0, lineHeight: 1.5 }}>
              {quoteData?.quote || title}
            </p>
            <p style={{ fontSize: 20, color: colors.muted, marginTop: 20, textAlign: "right" }}>
              — {quoteData?.author || subtitle}
            </p>
          </div>
        );
      }

      // ===== Hero =====
      case 'hero': {
        const heroData = data as { badge?: string; cta?: string };
        const pulseScale = 1 + Math.sin(frame * 0.08) * 0.02;
        return (
          <div style={{ textAlign: "center" }}>
            {heroData?.badge && (
              <div
                style={{
                  display: "inline-block",
                  padding: "10px 24px",
                  background: `${colors.blob2}15`,
                  backdropFilter: "blur(10px)",
                  borderRadius: 18,
                  border: `1px solid ${colors.blob2}40`,
                  fontSize: 18,
                  fontWeight: 600,
                  color: colors.blob2,
                  marginBottom: 20,
                  opacity: titleProgress,
                }}
              >
                {heroData.badge}
              </div>
            )}
            <h1
              style={{
                fontSize: 70,
                fontWeight: 700,
                color: colors.text,
                margin: 0,
                marginBottom: 20,
                letterSpacing: "-2px",
                lineHeight: 1.1,
              }}
            >
              {title}
            </h1>
            {subtitle && (
              <p style={{ fontSize: 30, color: colors.muted, margin: 0, marginBottom: 40 }}>
                {subtitle}
              </p>
            )}
            {heroData?.cta && (
              <div
                style={{
                  display: "inline-block",
                  padding: "20px 48px",
                  background: `linear-gradient(135deg, ${colors.blob1}, ${colors.blob2})`,
                  borderRadius: 32,
                  fontSize: 26,
                  fontWeight: 600,
                  color: "white",
                  transform: `scale(${pulseScale})`,
                  boxShadow: `0 10px 40px ${colors.blob1}40`,
                }}
              >
                {heroData.cta}
              </div>
            )}
          </div>
        );
      }

      // ===== CTA (行动收束页) =====
      case 'cta': {
        const ctaData = data as { cta?: string; button?: string; items?: string[]; badge?: string };
        const ctaText = ctaData?.cta || ctaData?.button || '点赞收藏';
        const tags = Array.isArray(ctaData?.items) ? ctaData.items : [];
        const pulseScale = 1 + Math.sin(frame * 0.12) * 0.04;
        const titleA = spring({ frame: frame - 6, fps, config: { damping: 14 } });
        const ctaA = spring({ frame: frame - 24, fps, config: { damping: 12, stiffness: 110 } });
        return (
          <div style={{ textAlign: 'center', maxWidth: 820 }}>
            <div
              style={{
                display: 'inline-block',
                padding: '10px 22px',
                borderRadius: 999,
                background: 'rgba(255,255,255,0.7)',
                backdropFilter: 'blur(14px)',
                border: `1px solid ${colors.blob2}45`,
                fontSize: 18,
                fontWeight: 700,
                color: colors.blob2,
                letterSpacing: '0.16em',
                textTransform: 'uppercase',
                marginBottom: 26,
                boxShadow: '0 14px 30px rgba(180,200,230,0.18)',
                opacity: titleA,
              }}
            >
              {ctaData?.badge ?? '◆ FIN'}
            </div>
            <h1
              style={{
                fontSize: 64,
                fontWeight: 800,
                color: colors.text,
                margin: 0,
                marginBottom: 18,
                lineHeight: 1.12,
                letterSpacing: '-1.2px',
                opacity: titleA,
                transform: `translateY(${interpolate(titleA, [0, 1], [22, 0])}px)`,
              }}
            >
              {title}
            </h1>
            {subtitle && (
              <p
                style={{
                  fontSize: 26,
                  color: colors.muted,
                  margin: '0 0 36px',
                  opacity: titleA,
                }}
              >
                {subtitle}
              </p>
            )}
            <div
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 12,
                padding: '24px 52px',
                background: `linear-gradient(135deg, ${colors.blob1}, ${colors.blob2})`,
                borderRadius: 999,
                fontSize: 30,
                fontWeight: 700,
                color: 'white',
                boxShadow: `0 22px 60px ${colors.blob1}55, inset 0 1px 0 rgba(255,255,255,0.45)`,
                transform: `scale(${pulseScale * interpolate(ctaA, [0, 1], [0.85, 1])})`,
                opacity: ctaA,
              }}
            >
              <span style={{ fontSize: 26 }}>→</span>
              {ctaText}
            </div>
            {tags.length > 0 && (
              <div
                style={{
                  marginTop: 30,
                  display: 'flex',
                  gap: 12,
                  justifyContent: 'center',
                  flexWrap: 'wrap',
                  opacity: ctaA,
                }}
              >
                {tags.slice(0, 4).map((t, i) => {
                  const tagColor = [colors.blob1, colors.blob2, colors.blob3, colors.blob4][i % 4];
                  return (
                    <span
                      key={i}
                      style={{
                        padding: '10px 18px',
                        borderRadius: 999,
                        background: 'rgba(255,255,255,0.65)',
                        backdropFilter: 'blur(10px)',
                        border: `1px solid ${tagColor}45`,
                        fontSize: 17,
                        fontWeight: 700,
                        color: colors.text,
                      }}
                    >
                      #{t}
                    </span>
                  );
                })}
              </div>
            )}
          </div>
        );
      }

      // ===== Default =====
      default:
        return points && points.length > 0 ? (
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: 14,
              width: "100%",
            }}
          >
            {points.map((point, i) => {
              const progress = pointProgresses[i] || 0;
              const pointColor = [colors.blob1, colors.blob2, colors.blob3, colors.blob4, colors.blob5, colors.blob6][i % 6];

              return (
                <div
                  key={i}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 18,
                    padding: "20px 24px",
                    background: "rgba(255,255,255,0.5)",
                    backdropFilter: "blur(10px)",
                    borderRadius: 22,
                    border: "1px solid rgba(255,255,255,0.7)",
                    boxShadow: `0 2px 8px rgba(0,0,0,0.03), inset 0 1px 1px rgba(255,255,255,0.8)`,
                    transform: `translateX(${interpolate(progress, [0, 1], [-30, 0])}px)`,
                    opacity: progress,
                  }}
                >
                  <div
                    style={{
                      width: 42,
                      height: 42,
                      borderRadius: "50%",
                      background: `linear-gradient(135deg, ${pointColor}, ${pointColor}cc)`,
                      display: "flex",
                      justifyContent: "center",
                      alignItems: "center",
                      fontSize: 18,
                      fontWeight: 600,
                      color: "white",
                      boxShadow: `0 4px 14px ${pointColor}40`,
                      flexShrink: 0,
                    }}
                  >
                    {i + 1}
                  </div>
                  <span style={{ fontSize: 26, color: colors.text, fontWeight: 500 }}>
                    {point}
                  </span>
                </div>
              );
            })}
          </div>
        ) : null;
    }
  };

  // 计算卡片尺寸
  const getCardSize = () => {
    if (type === 'hero') return { width: 900, padding: "60px 50px" };
    if (type === 'stats') return { width: 920, padding: "55px 45px" };
    if (type === 'compare') return { width: 880, padding: "50px 40px" };
    if (type === 'quote') return { width: 800, padding: "50px 45px" };
    return { width: 880, padding: "60px 50px" };
  };

  const cardSize = getCardSize();

  return (
    <AbsoluteFill
      style={{
        background: colors.bg,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'SF Pro Display', 'PingFang SC', sans-serif",
        overflow: "hidden",
      }}
    >
      <GradientBackground frame={frame} />

      <MegaBlob frame={frame} x={-200} y={-100} size={700} color={colors.blob1} speedX={0.006} speedY={0.005} phase={0} />
      <MegaBlob frame={frame} x={600} y={0} size={800} color={colors.blob2} speedX={0.005} speedY={0.006} phase={2} />
      <MegaBlob frame={frame} x={100} y={600} size={750} color={colors.blob3} speedX={0.007} speedY={0.005} phase={4} />
      <MegaBlob frame={frame} x={550} y={900} size={650} color={colors.blob4} speedX={0.0055} speedY={0.0065} phase={1} />
      <MegaBlob frame={frame} x={-150} y={1200} size={600} color={colors.blob5} speedX={0.0065} speedY={0.0055} phase={3} />
      <MegaBlob frame={frame} x={650} y={1300} size={700} color={colors.blob6} speedX={0.005} speedY={0.007} phase={5} />

      <FloatingSphere frame={frame} x={80} y={280} size={28} color={colors.blob2} delay={8} />
      <FloatingSphere frame={frame} x={920} y={380} size={22} color={colors.blob3} delay={12} />
      <FloatingSphere frame={frame} x={100} y={750} size={24} color={colors.blob1} delay={10} />
      <FloatingSphere frame={frame} x={890} y={850} size={26} color={colors.blob5} delay={15} />
      <FloatingSphere frame={frame} x={70} y={1300} size={20} color={colors.blob4} delay={18} />
      <FloatingSphere frame={frame} x={940} y={1400} size={24} color={colors.blob6} delay={6} />

      <AbsoluteFill
        style={{
          opacity: exitOpacity,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          padding: "50px",
          zIndex: 10,
        }}
      >
        {/* 顶部信息栏 */}
        <div
          style={{
            position: "absolute",
            top: 50,
            left: 50,
            right: 50,
            display: "flex",
            justifyContent: "flex-end",
            alignItems: "center",
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 6,
              padding: "8px 16px",
              background: "rgba(255,255,255,0.55)",
              backdropFilter: "blur(20px)",
              borderRadius: 18,
              border: "1px solid rgba(255,255,255,0.75)",
            }}
          >
            <span style={{ fontSize: 18, fontWeight: 600, color: colors.text }}>{index + 1}</span>
            <span style={{ fontSize: 18, color: colors.muted }}>/</span>
            <span style={{ fontSize: 18, color: colors.muted }}>{totalSlides}</span>
          </div>
        </div>

        {/* 主玻璃卡片 */}
        <LiquidGlassCard frame={frame} delay={8} width={cardSize.width} padding={cardSize.padding}>
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              position: "relative",
              zIndex: 2,
            }}
          >
            {/* 标题区域 */}
            {type !== 'hero' && type !== 'quote' && (
              <>
                <h1
                  style={{
                    fontSize: type === 'stats' || type === 'compare' ? 48 : 56,
                    fontWeight: 700,
                    color: colors.text,
                    margin: 0,
                    marginBottom: 10,
                    transform: `translateY(${interpolate(titleProgress, [0, 1], [20, 0])}px)`,
                    opacity: titleProgress,
                    letterSpacing: "-1px",
                    textAlign: "center",
                  }}
                >
                  {title}
                </h1>

                <div
                  style={{
                    width: interpolate(titleProgress, [0, 1], [0, 80]),
                    height: 5,
                    borderRadius: 3,
                    background: `linear-gradient(90deg, ${colors.blob1}, ${colors.blob2}, ${colors.blob3}, ${colors.blob4})`,
                    marginBottom: subtitle ? 12 : 28,
                    boxShadow: `0 2px 10px ${colors.blob2}40`,
                  }}
                />

                {subtitle && (
                  <p
                    style={{
                      fontSize: 26,
                      color: colors.muted,
                      margin: 0,
                      marginBottom: 32,
                      transform: `translateY(${interpolate(subtitleProgress, [0, 1], [14, 0])}px)`,
                      opacity: subtitleProgress,
                      fontWeight: 400,
                    }}
                  >
                    {subtitle}
                  </p>
                )}
              </>
            )}

            {/* 内容区域 */}
            {renderContent()}
          </div>
        </LiquidGlassCard>

        {/* 底部指示器 */}
        <div
          style={{
            position: "absolute",
            bottom: 50,
            display: "flex",
            gap: 8,
          }}
        >
          {[...Array(totalSlides)].map((_, i) => (
            <div
              key={i}
              style={{
                width: i === index ? 32 : 10,
                height: 10,
                borderRadius: 5,
                background: i === index
                  ? `linear-gradient(90deg, ${colors.blob1}, ${colors.blob2})`
                  : "rgba(0,0,0,0.1)",
                boxShadow: i === index ? `0 2px 8px ${colors.blob1}40` : "none",
              }}
            />
          ))}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};
