import React from "react";
import { AbsoluteFill, Audio, Sequence, staticFile, useVideoConfig } from "remotion";
import { StudioSlide } from "./StudioSlide";
import { getSlideTiming, getStaticAssetPath, useContentJson } from "../hooks/useContentJson";
import { getTemplateContentPath } from "../project-content";
import { SubtitleOverlay } from "../renderers/SubtitleOverlay";

const defaultSlides = [
  {
    title: "把横屏视频做成演播室级信息墙",
    subtitle: "更适合数据复盘、项目总结、策略拆解和报告型内容",
    type: "hero" as const,
    data: {
      badge: "landscape control room",
      cta: "Open the signal board",
      items: ["数据主屏", "证据中段", "明确收束"],
    },
  },
  {
    title: "横屏里最适合摆证据而不是堆文案",
    subtitle: "一边讲逻辑，一边给图表、对比、次级信息留空间",
    type: "compare" as const,
    data: {
      left: { label: "堆文本", value: "信息平铺", desc: "读者只能顺着念，抓不到焦点" },
      right: { label: "演播室布局", value: "主次并行", desc: "标题、证据、补充信息能同时成立" },
    },
  },
  {
    title: "中段至少给一页真正的指标页",
    subtitle: "横屏的优势不是更宽，而是能把结论和证据一起摆出来",
    type: "stats" as const,
    data: {
      stats: [
        { value: 87, suffix: "%", label: "信息聚焦度" },
        { value: 3.4, suffix: "x", label: "证据承载量" },
        { value: 18, suffix: "s", label: "结论进入时间" },
      ],
    },
  },
  {
    title: "最后一页就让用户知道下一步",
    subtitle: "先给结论，再给行动，不要把横屏视频收在空话里",
    type: "cta" as const,
    data: {
      cta: "用 StudioShow 做下一条横屏复盘",
      items: ["复盘", "汇报", "数据讲解"],
    },
  },
];

const DEFAULT_SLIDE_DURATION = 150;
const CONTENT_PATH = getTemplateContentPath("StudioShow");

export const StudioShow: React.FC = () => {
  const { fps } = useVideoConfig();
  const { slides, soundtrackPath } = useContentJson(defaultSlides, {
    expectedTemplate: "StudioShow",
    contentPath: CONTENT_PATH,
  });
  const soundtrackSrc = getStaticAssetPath(soundtrackPath);

  return (
    <AbsoluteFill style={{ background: "#060914" }}>
      {soundtrackSrc ? <Audio src={staticFile(soundtrackSrc)} /> : null}
      <SubtitleOverlay slides={slides} template="StudioShow" />
      {slides.map((slide, index) => {
        const { from, duration } = getSlideTiming(slides, index, fps, DEFAULT_SLIDE_DURATION);

        return (
          <Sequence key={index} from={from} durationInFrames={duration}>
            <StudioSlide
              title={slide.title || ""}
              subtitle={slide.subtitle}
              points={(slide as { points?: string[] }).points}
              type={(slide as { type?: string }).type as React.ComponentProps<typeof StudioSlide>["type"]}
              data={(slide as { data?: Record<string, unknown> }).data}
              index={index}
              totalSlides={slides.length}
              durationInFrames={duration}
            />
          </Sequence>
        );
      })}
    </AbsoluteFill>
  );
};
